<section class="admin-page-head"><div><p class="admin-kicker">TRAZABILIDAD</p><h1>Auditoría</h1><p>Eventos sensibles de acceso y administración. Esta bitácora es de solo lectura.</p></div></section>
<section class="admin-panel admin-table-panel"><?php if ($events === []): ?><p class="admin-empty">No hay eventos registrados.</p><?php else: ?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Fecha</th><th>Actor</th><th>Acción</th><th>Recurso</th><th>Resultado</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= e($event['created_at']) ?></td><td><?= e($event['actor_name'] ?? 'Sistema / anónimo') ?></td><td><code><?= e($event['action']) ?></code></td><td><?= e($event['resource']) ?><?= $event['resource_id'] !== null ? ' #' . e($event['resource_id']) : '' ?></td><td><span class="admin-status <?= $event['outcome'] === 'success' ? 'is-active' : 'is-danger' ?>"><?= e($event['outcome']) ?></span></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
